// DeleteFolder is the resolver for the deleteFolder field.
func (r *mutationResolver) DeleteFolder(ctx context.Context, folderID string) (bool, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return false, fmt.Errorf("authentication required: %v", err)
	}

	// Check if folder exists and user owns it
	var ownerID string
	err = r.DB.QueryRow(ctx, "SELECT owner_id FROM folders WHERE id = $1", folderID).Scan(&ownerID)
	if err != nil {
		return false, fmt.Errorf("folder not found: %v", err)
	}

	if ownerID != user.ID {
		return false, fmt.Errorf("you can only delete your own folders")
	}

	// Check if folder has files or subfolders
	var fileCount, subfolderCount int
	r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM files WHERE folder_id = $1", folderID).Scan(&fileCount)
	r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM folders WHERE parent_id = $1", folderID).Scan(&subfolderCount)

	if fileCount > 0 || subfolderCount > 0 {
		return false, fmt.Errorf("folder is not empty")
	}

	_, err = r.DB.Exec(ctx, "DELETE FROM folders WHERE id = $1", folderID)
	if err != nil {
		return false, fmt.Errorf("failed to delete folder: %v", err)
	}

	return true, nil
}

