// ListFiles is the resolver for the listFiles field.
func (r *queryResolver) ListFiles(ctx context.Context, folderID *string) ([]*model.File, error) {
	// Get authenticated user
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	query := `SELECT id, filename, filetype, filesize, filehash, is_public, is_public_shared, 
	public_share_enabled_at, public_share_enabled_by, created_at, owner_id FROM files WHERE owner_id = $1`
	args := []interface{}{user.ID}

	if folderID != nil {
		query += " AND folder_id = $2"
		args = append(args, *folderID)
	} else {
		// When no folder is specified, only show files that don't belong to any folder
		query += " AND folder_id IS NULL"
	}

	query += " ORDER BY created_at DESC"

	rows, err := r.DB.Query(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("failed to list files: %v", err)
	}
	defer rows.Close()

	var files []*model.File
	for rows.Next() {
		var file model.File
		var createdAt time.Time
		var publicShareEnabledAt *time.Time
		var publicShareEnabledByID *string
		var fileOwnerID string
		err := rows.Scan(&file.ID, &file.Filename, &file.Filetype, &file.Filesize, &file.Filehash,
			&file.IsPublic, &file.IsPublicShared, &publicShareEnabledAt, &publicShareEnabledByID,
			&createdAt, &fileOwnerID)
		if err != nil {
			return nil, fmt.Errorf("failed to scan file: %v", err)
		}

		// Convert timestamp to string
		file.CreatedAt = createdAt.Format(time.RFC3339)

		// Handle public share timestamp
		if publicShareEnabledAt != nil {
			enabledAtStr := publicShareEnabledAt.Format(time.RFC3339)
			file.PublicShareEnabledAt = &enabledAtStr
		}

		// Generate filepath (S3 key or URL)
		file.Filepath = fmt.Sprintf("uploads/%s", file.Filehash)

		// Get owner information
		var owner model.User
		err = r.DB.QueryRow(ctx,
			"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
			fileOwnerID,
		).Scan(&owner.ID, &owner.Username, &owner.Email, &owner.Role)
		if err != nil {
			return nil, fmt.Errorf("failed to get owner: %v", err)
		}
		file.Owner = &owner

		// Get public share enabled by user info if applicable
		if publicShareEnabledByID != nil {
			var enabledByUser model.User
			err = r.DB.QueryRow(ctx,
				"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
				*publicShareEnabledByID,
			).Scan(&enabledByUser.ID, &enabledByUser.Username, &enabledByUser.Email, &enabledByUser.Role)
			if err == nil {
				file.PublicShareEnabledBy = &enabledByUser
			}
		}

		files = append(files, &file)
	}

	return files, nil
}

