// SearchFiles is the resolver for the searchFiles field.
func (r *queryResolver) SearchFiles(ctx context.Context, query *string, mimeTypes []string, sizeMin *int32, sizeMax *int32, dateFrom *string, dateTo *string, uploaderName *string, folderID *string, sortBy *string, sortDirection *string, limit *int32, offset *int32) (*model.SearchResult, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("user not authenticated: %v", err)
	}

	// Set defaults
	if limit == nil || *limit <= 0 || *limit > 100 {
		defaultLimit := int32(50)
		limit = &defaultLimit
	}
	if offset == nil || *offset < 0 {
		defaultOffset := int32(0)
		offset = &defaultOffset
	}
	if sortBy == nil {
		defaultSort := "created_at"
		sortBy = &defaultSort
	}
	if sortDirection == nil {
		defaultDirection := "DESC"
		sortDirection = &defaultDirection
	}

	// Build search query with conditions
	var conditions []string
	var args []interface{}
	argIndex := 1

	// Base security condition - user can only see their files, shared files, or public files
	conditions = append(conditions, fmt.Sprintf("(f.owner_id = $%d OR f.is_public = true OR EXISTS(SELECT 1 FROM file_shares fs WHERE fs.file_id = f.id AND fs.shared_with = $%d))", argIndex, argIndex))
	args = append(args, user.ID)
	argIndex++

	// Filename search
	if query != nil && *query != "" {
		conditions = append(conditions, fmt.Sprintf("f.filename ILIKE $%d", argIndex))
		args = append(args, "%"+*query+"%")
		argIndex++
	}

	// MIME type filter
	if mimeTypes != nil && len(mimeTypes) > 0 {
		var mimeConditions []string
		for _, mimeType := range mimeTypes {
			if mimeType != "" {
				mimeConditions = append(mimeConditions, fmt.Sprintf("f.filetype ILIKE $%d", argIndex))
				args = append(args, mimeType)
				argIndex++
			}
		}
		if len(mimeConditions) > 0 {
			conditions = append(conditions, "("+strings.Join(mimeConditions, " OR ")+")")
		}
	}

	// Size range filter
	if sizeMin != nil && *sizeMin > 0 {
		conditions = append(conditions, fmt.Sprintf("f.filesize >= $%d", argIndex))
		args = append(args, *sizeMin)
		argIndex++
	}
	if sizeMax != nil && *sizeMax > 0 {
		conditions = append(conditions, fmt.Sprintf("f.filesize <= $%d", argIndex))
		args = append(args, *sizeMax)
		argIndex++
	}

	// Date range filter
	if dateFrom != nil && *dateFrom != "" {
		conditions = append(conditions, fmt.Sprintf("f.created_at >= $%d", argIndex))
		args = append(args, *dateFrom)
		argIndex++
	}
	if dateTo != nil && *dateTo != "" {
		conditions = append(conditions, fmt.Sprintf("f.created_at <= $%d", argIndex))
		args = append(args, *dateTo+" 23:59:59")
		argIndex++
	}

	// Uploader name filter
	if uploaderName != nil && *uploaderName != "" {
		conditions = append(conditions, fmt.Sprintf("u.username ILIKE $%d", argIndex))
		args = append(args, "%"+*uploaderName+"%")
		argIndex++
	}

	// Folder filter
	if folderID != nil && *folderID != "" {
		if *folderID == "root" {
			conditions = append(conditions, "f.folder_id IS NULL")
		} else {
			conditions = append(conditions, fmt.Sprintf("f.folder_id = $%d", argIndex))
			args = append(args, *folderID)
			argIndex++
		}
	}

	// Validate sort field
	validSortFields := map[string]string{
		"filename":   "f.filename",
		"filesize":   "f.filesize",
		"created_at": "f.created_at",
		"filetype":   "f.filetype",
	}
	sortField, exists := validSortFields[*sortBy]
	if !exists {
		sortField = "f.created_at"
	}

	// Validate sort direction
	direction := "DESC"
	if *sortDirection == "ASC" || *sortDirection == "asc" {
		direction = "ASC"
	}

	// Build main query
	whereClause := "WHERE " + strings.Join(conditions, " AND ")

	mainQuery := fmt.Sprintf(`
		SELECT f.id, f.filename, f.filetype, f.filesize, f.filehash,
			   f.is_public, f.is_public_shared, f.public_share_enabled_at, f.created_at, f.owner_id,
			   u.username, u.email, u.role,
			   fo.id as folder_id, fo.name as folder_name,
			   pseu.username as public_share_enabled_by_username
		FROM files f
		JOIN users u ON f.owner_id = u.id
		LEFT JOIN folders fo ON f.folder_id = fo.id
		LEFT JOIN users pseu ON f.public_share_enabled_by = pseu.id
		%s
		ORDER BY %s %s
		LIMIT $%d OFFSET $%d
	`, whereClause, sortField, direction, argIndex, argIndex+1)

	args = append(args, *limit, *offset)

	// Execute main query
	rows, err := r.DB.Query(ctx, mainQuery, args...)
	if err != nil {
		return nil, fmt.Errorf("failed to search files: %v", err)
	}
	defer rows.Close()

	var files []*model.File
	for rows.Next() {
		var file model.File
		var owner model.User
		var createdAt time.Time
		var publicShareEnabledAt *time.Time
		var folderID *string
		var folderName *string
		var publicShareEnabledByUsername *string

		err := rows.Scan(
			&file.ID, &file.Filename, &file.Filetype, &file.Filesize, &file.Filehash,
			&file.IsPublic, &file.IsPublicShared, &publicShareEnabledAt, &createdAt, &owner.ID,
			&owner.Username, &owner.Email, &owner.Role,
			&folderID, &folderName, &publicShareEnabledByUsername,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan file: %v", err)
		}

		// Set timestamps
		file.CreatedAt = createdAt.Format(time.RFC3339)
		if publicShareEnabledAt != nil {
			timeStr := publicShareEnabledAt.Format(time.RFC3339)
			file.PublicShareEnabledAt = &timeStr
		}

		// Generate filepath from filehash
		file.Filepath = fmt.Sprintf("uploads/%s", file.Filehash)

		// Set owner
		file.Owner = &owner

		// Set folder if exists
		if folderID != nil && folderName != nil {
			file.Folder = &model.Folder{
				ID:   *folderID,
				Name: *folderName,
			}
		}

		// Set public share enabled by user if exists
		if publicShareEnabledByUsername != nil {
			file.PublicShareEnabledBy = &model.User{
				Username: *publicShareEnabledByUsername,
			}
		}

		files = append(files, &file)
	}

	// Get total count
	countQuery := fmt.Sprintf(`
		SELECT COUNT(*)
		FROM files f
		JOIN users u ON f.owner_id = u.id
		LEFT JOIN folders fo ON f.folder_id = fo.id
		%s
	`, whereClause)

	var totalCount int32
	err = r.DB.QueryRow(ctx, countQuery, args[:len(args)-2]...).Scan(&totalCount)
	if err != nil {
		return nil, fmt.Errorf("failed to get total count: %v", err)
	}

	// Generate facets for better search experience
	// TODO: Fix generateSearchFacets method
	// facets, err := r.generateSearchFacets(ctx, conditions, args[:len(args)-2])
	// if err != nil {
	//	// Don't fail the whole query if facets fail
	facets := &model.SearchFacets{
		MimeTypes:   []*model.MimeTypeFacet{},
		Uploaders:   []*model.UploaderFacet{},
		SizeBuckets: []*model.SizeBucketFacet{},
	}
	// }

	hasMore := int32(*offset)+int32(len(files)) < totalCount

	return &model.SearchResult{
		Files:      files,
		TotalCount: totalCount,
		HasMore:    hasMore,
		Facets:     facets,
	}, nil
}

// ListSharedFiles is the resolver for the listSharedFiles field.
func (r *queryResolver) ListSharedFiles(ctx context.Context) ([]*model.FileShares, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	rows, err := r.DB.Query(ctx,
		`SELECT id, file_id, shared_with, permission, shared_by 
		 FROM file_shares 
		 WHERE shared_with = $1 OR shared_by = $1`,
		user.ID,
	)
	if err != nil {
		return nil, fmt.Errorf("failed to list shared files: %v", err)
	}
	defer rows.Close()

	var shares []*model.FileShares
	for rows.Next() {
		var share model.FileShares
		var fileID, sharedWithID, sharedByID string
		err := rows.Scan(&share.ID, &fileID, &sharedWithID, &share.Permission, &sharedByID)
		if err != nil {
			return nil, fmt.Errorf("failed to scan share: %v", err)
		}

		// Get file information using the fileID variable
		var file model.File
		var createdAt time.Time
		var fileOwnerID string
		err = r.DB.QueryRow(ctx,
			"SELECT id, filename, filetype, filesize, filehash, is_public, created_at, owner_id FROM files WHERE id = $1",
			fileID,
		).Scan(&file.ID, &file.Filename, &file.Filetype, &file.Filesize, &file.Filehash, &file.IsPublic, &createdAt, &fileOwnerID)
		if err != nil {
			continue
		}

		file.CreatedAt = createdAt.Format(time.RFC3339)
		file.Filepath = fmt.Sprintf("uploads/%s", file.Filehash)

		// Get file owner information
		var fileOwner model.User
		err = r.DB.QueryRow(ctx,
			"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
			fileOwnerID,
		).Scan(&fileOwner.ID, &fileOwner.Username, &fileOwner.Email, &fileOwner.Role)
		if err != nil {
			continue
		}
		file.Owner = &fileOwner

		// Get shared with user information
		var sharedWith model.User
		err = r.DB.QueryRow(ctx,
			"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
			sharedWithID,
		).Scan(&sharedWith.ID, &sharedWith.Username, &sharedWith.Email, &sharedWith.Role)
		if err != nil {
			continue
		}

		// Get shared by user information
		var sharedBy model.User
		err = r.DB.QueryRow(ctx,
			"SELECT id, username, email, COALESCE(role, 'user') FROM users WHERE id = $1",
			sharedByID,
		).Scan(&sharedBy.ID, &sharedBy.Username, &sharedBy.Email, &sharedBy.Role)
		if err != nil {
			continue
		}

		// Populate the share object with all details
		share.File = &file
		share.SharedWith = &sharedWith
		share.SharedBy = &sharedBy

		shares = append(shares, &share)
	}

	return shares, nil
}

// ListPublicFiles is the resolver for the listPublicFiles field.
func (r *queryResolver) ListPublicFiles(ctx context.Context) ([]*model.PublicFile, error) {
	_, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	rows, err := r.DB.Query(ctx,
		`SELECT f.id, f.filename, f.filetype, f.filesize, f.created_at, f.public_share_enabled_at, f.owner_id,
				u.id, u.username, u.email, u.role,
				COALESCE(download_stats.download_count, 0) as download_count
		 FROM files f
		 JOIN users u ON f.owner_id = u.id
		 LEFT JOIN (
			SELECT file_id, COUNT(*) as download_count 
			FROM file_downloads 
			GROUP BY file_id
		 ) download_stats ON f.id = download_stats.file_id
		 WHERE f.is_public_shared = TRUE
		 ORDER BY f.public_share_enabled_at DESC`)
	if err != nil {
		return nil, fmt.Errorf("failed to list public files: %v", err)
	}
	defer rows.Close()

	var publicFiles []*model.PublicFile
	for rows.Next() {
		var publicFile model.PublicFile
		var owner model.User
		var createdAt, publicSharedAt time.Time

		err := rows.Scan(
			&publicFile.ID, &publicFile.Filename, &publicFile.Filetype, &publicFile.Filesize,
			&createdAt, &publicSharedAt,
			&owner.ID, &owner.ID, &owner.Username, &owner.Email, &owner.Role,
			&publicFile.DownloadCount,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan public file: %v", err)
		}

		publicFile.CreatedAt = createdAt.Format(time.RFC3339)
		publicFile.PublicSharedAt = publicSharedAt.Format(time.RFC3339)
		publicFile.Owner = &owner

		publicFiles = append(publicFiles, &publicFile)
	}

	return publicFiles, nil
}

// GetFileDownloadStats is the resolver for the getFileDownloadStats field.
func (r *queryResolver) GetFileDownloadStats(ctx context.Context, fileID string) (*model.FileDownloadStats, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	// Check if the user owns the file or is admin
	var ownerID string
	err = r.DB.QueryRow(ctx, "SELECT owner_id FROM files WHERE id = $1", fileID).Scan(&ownerID)
	if err != nil {
		return nil, fmt.Errorf("file not found: %v", err)
	}

	if ownerID != user.ID && user.Role != "admin" {
		return nil, fmt.Errorf("permission denied: you can only view stats for your own files")
	}

	// Get total download count
	var totalDownloads int32
	err = r.DB.QueryRow(ctx,
		"SELECT COUNT(*) FROM file_downloads WHERE file_id = $1",
		fileID).Scan(&totalDownloads)
	if err != nil {
		return nil, fmt.Errorf("failed to get download count: %v", err)
	}

	// Get detailed download records
	rows, err := r.DB.Query(ctx,
		`SELECT fd.id, fd.downloaded_at, fd.ip_address, fd.downloaded_by,
				u.id, u.username, u.email, u.role
		 FROM file_downloads fd
		 LEFT JOIN users u ON fd.downloaded_by = u.id
		 WHERE fd.file_id = $1
		 ORDER BY fd.downloaded_at DESC
		 LIMIT 100`, // Limit to most recent 100 downloads
		fileID)
	if err != nil {
		return nil, fmt.Errorf("failed to get download history: %v", err)
	}
	defer rows.Close()

	var downloads []*model.FileDownload
	for rows.Next() {
		var download model.FileDownload
		var downloadedAt time.Time
		var downloadedByID *string
		var userID, username, email, role *string

		err := rows.Scan(
			&download.ID, &downloadedAt, &download.IPAddress, &downloadedByID,
			&userID, &username, &email, &role,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan download record: %v", err)
		}

		download.DownloadedAt = downloadedAt.Format(time.RFC3339)
		if downloadedByID != nil && userID != nil && username != nil && email != nil && role != nil {
			download.DownloadedBy = &model.User{
				ID:       *userID,
				Username: *username,
				Email:    *email,
				Role:     *role,
			}
		}

		downloads = append(downloads, &download)
	}

	return &model.FileDownloadStats{
		TotalDownloads: totalDownloads,
		Downloads:      downloads,
	}, nil
}

// GetDownloadURL is the resolver for the getDownloadUrl field.
func (r *queryResolver) GetDownloadURL(ctx context.Context, fileID string) (string, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return "", fmt.Errorf("user not authenticated: %v", err)
	}

	// Query file and get the storage key from content table
	var filename, filehash string
	var isPublic bool
	var ownerID string
	query := `
		SELECT f.filename, f.filehash, f.is_public, f.owner_id
		FROM files f
		WHERE f.id = $1 AND (f.owner_id = $2 OR f.is_public = true OR 
			EXISTS(SELECT 1 FROM file_shares fs WHERE fs.file_id = f.id AND fs.shared_with = $2))
	`

	err = r.DB.QueryRow(ctx, query, fileID, user.ID).Scan(
		&filename, &filehash, &isPublic, &ownerID,
	)
	if err != nil {
		return "", fmt.Errorf("file not found or access denied: %v", err)
	}

	// Get storage key from content table
	var storageKey string
	err = r.DB.QueryRow(ctx, "SELECT storage_key FROM content WHERE sha256 = $1", filehash).Scan(&storageKey)
	if err != nil {
		return "", fmt.Errorf("content not found: %v", err)
	}

	// Create AWS session and S3 client
	sess, err := session.NewSession(&aws.Config{
		Region: aws.String("eu-north-1"),
	})
	if err != nil {
		return "", fmt.Errorf("failed to create AWS session: %v", err)
	}
	s3Client := s3.New(sess)

	// Generate a presigned URL for download (valid for 1 hour)
	req, _ := s3Client.GetObjectRequest(&s3.GetObjectInput{
		Bucket: aws.String("go-drive-v2"),
		Key:    aws.String(storageKey),
	})

	downloadURL, err := req.Presign(1 * time.Hour)
	if err != nil {
		return "", fmt.Errorf("failed to generate download URL: %v", err)
	}

	// Log file download audit event
	go r.AuditLogger.LogFileDownload(context.Background(), user.ID, fileID, filename, nil)

	return downloadURL, nil
}

// ListFolders is the resolver for the listFolders field.
func (r *queryResolver) ListFolders(ctx context.Context, parentID *string) ([]*model.Folder, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	query := "SELECT id, name, created_at FROM folders WHERE owner_id = $1"
	args := []interface{}{user.ID}

	if parentID != nil {
		query += " AND parent_id = $2"
		args = append(args, *parentID)
	} else {
		query += " AND parent_id IS NULL"
	}

	query += " ORDER BY name"

	rows, err := r.DB.Query(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("failed to list folders: %v", err)
	}
	defer rows.Close()

	var folders []*model.Folder
	for rows.Next() {
		var folder model.Folder
		var createdAt time.Time
		err := rows.Scan(&folder.ID, &folder.Name, &createdAt)
		if err != nil {
			return nil, fmt.Errorf("failed to scan folder: %v", err)
		}

		// Convert timestamp to string
		folder.CreatedAt = createdAt.Format(time.RFC3339)

		// Set owner information (we already have it from auth context)
		folder.Owner = &model.User{
			ID:       user.ID,
			Username: user.Username,
			Email:    user.Email,
			Role:     user.Role,
		}

		folders = append(folders, &folder)
	}

	return folders, nil
}

// GetUserStatistics is the resolver for the getUserStatistics field.
func (r *queryResolver) GetUserStatistics(ctx context.Context) (*model.UserStatistics, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	// Get user's file count
	var fileCount int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM files WHERE owner_id = $1", user.ID).Scan(&fileCount)
	if err != nil {
		return nil, fmt.Errorf("failed to get file count: %v", err)
	}

	// Get total storage used by user
	var totalUsed int
	err = r.DB.QueryRow(ctx, "SELECT COALESCE(SUM(filesize), 0) FROM files WHERE owner_id = $1", user.ID).Scan(&totalUsed)
	if err != nil {
		return nil, fmt.Errorf("failed to get storage usage: %v", err)
	}

	// Calculate original size (estimate based on typical compression ratios)
	originalSize := int(float64(totalUsed) * 1.2) // Assume 20% compression savings
	savingsBytes := originalSize - totalUsed
	savingsPercentage := float64(0)
	if originalSize > 0 {
		savingsPercentage = (float64(savingsBytes) / float64(originalSize)) * 100
	}

	// Get shared files count (files shared by this user)
	var totalSharedFiles int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM file_shares WHERE shared_by = $1", user.ID).Scan(&totalSharedFiles)
	if err != nil {
		return nil, fmt.Errorf("failed to get shared files count: %v", err)
	}

	// Get received shares count (files shared with this user)
	var totalReceivedShares int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM file_shares WHERE shared_with = $1", user.ID).Scan(&totalReceivedShares)
	if err != nil {
		return nil, fmt.Errorf("failed to get received shares count: %v", err)
	}

	return &model.UserStatistics{
		TotalUsed:           int32(totalUsed),
		OriginalSize:        int32(originalSize),
		SavingsBytes:        int32(savingsBytes),
		SavingsPercentage:   savingsPercentage,
		FileCount:           int32(fileCount),
		TotalSharedFiles:    int32(totalSharedFiles),
		TotalReceivedShares: int32(totalReceivedShares),
	}, nil
}

// GetAdminStatistics is the resolver for the getAdminStatistics field.
func (r *queryResolver) GetAdminStatistics(ctx context.Context) (*model.AdminStatistics, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	// Check if user is admin
	if user.Role != "admin" {
		return nil, fmt.Errorf("admin access required")
	}

	// Get total users
	var totalUsers int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM users").Scan(&totalUsers)
	if err != nil {
		return nil, fmt.Errorf("failed to get user count: %v", err)
	}

	// Get total files
	var totalFiles int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM files").Scan(&totalFiles)
	if err != nil {
		return nil, fmt.Errorf("failed to get file count: %v", err)
	}

	// Get total storage (sum of all file sizes)
	var totalStorage int
	err = r.DB.QueryRow(ctx, "SELECT COALESCE(SUM(filesize), 0) FROM files").Scan(&totalStorage)
	if err != nil {
		return nil, fmt.Errorf("failed to get storage usage: %v", err)
	}

	// Calculate storage savings (simplified calculation)
	totalSavings := 15 // Placeholder percentage

	// Get total public files
	var totalPublicFiles int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM files WHERE is_public_shared = TRUE").Scan(&totalPublicFiles)
	if err != nil {
		return nil, fmt.Errorf("failed to get public file count: %v", err)
	}

	// Get total public downloads
	var totalPublicDownloads int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM file_downloads").Scan(&totalPublicDownloads)
	if err != nil {
		return nil, fmt.Errorf("failed to get download count: %v", err)
	}

	// Get top downloaded files
	topFilesRows, err := r.DB.Query(ctx,
		`SELECT f.id, f.filename, f.public_share_enabled_at, f.owner_id,
				u.id, u.username, u.email, u.role,
				COUNT(fd.id) as download_count
		 FROM files f
		 JOIN users u ON f.owner_id = u.id
		 LEFT JOIN file_downloads fd ON f.id = fd.file_id
		 WHERE f.is_public_shared = TRUE
		 GROUP BY f.id, f.filename, f.public_share_enabled_at, f.owner_id, u.id, u.username, u.email, u.role
		 ORDER BY download_count DESC
		 LIMIT 5`)
	if err != nil {
		return nil, fmt.Errorf("failed to get top files: %v", err)
	}
	defer topFilesRows.Close()

	var topDownloadedFiles []*model.PublicFileStats
	for topFilesRows.Next() {
		var fileStats model.PublicFileStats
		var owner model.User
		var publicSharedAt time.Time
		var downloadCount int

		err := topFilesRows.Scan(
			&fileStats.ID, &fileStats.Filename, &publicSharedAt,
			&owner.ID, &owner.ID, &owner.Username, &owner.Email, &owner.Role,
			&downloadCount,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan top file: %v", err)
		}

		fileStats.DownloadCount = int32(downloadCount)

		topDownloadedFiles = append(topDownloadedFiles, &fileStats)
	}

	// Get recent downloads
	recentDownloadsRows, err := r.DB.Query(ctx,
		`SELECT fd.id, fd.downloaded_at, fd.ip_address, fd.downloaded_by,
				u.id, u.username, u.email, COALESCE(u.role, 'user')
		 FROM file_downloads fd
		 LEFT JOIN users u ON fd.downloaded_by = u.id
		 ORDER BY fd.downloaded_at DESC
		 LIMIT 10`)
	if err != nil {
		return nil, fmt.Errorf("failed to get recent downloads: %v", err)
	}
	defer recentDownloadsRows.Close()

	var recentDownloads []*model.FileDownload
	for recentDownloadsRows.Next() {
		var download model.FileDownload
		var downloadedAt time.Time
		var downloadedByID *string
		var userID, username, email, role *string

		err := recentDownloadsRows.Scan(
			&download.ID, &downloadedAt, &download.IPAddress, &downloadedByID,
			&userID, &username, &email, &role,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan recent download: %v", err)
		}

		download.DownloadedAt = downloadedAt.Format(time.RFC3339)

		// Set user info if available
		if downloadedByID != nil && userID != nil {
			download.DownloadedBy = &model.User{
				ID:       *userID,
				Username: *username,
				Email:    *email,
				Role:     *role,
			}
		}

		recentDownloads = append(recentDownloads, &download)
	}

	return &model.AdminStatistics{
		TotalUsers:           int32(totalUsers),
		TotalFiles:           int32(totalFiles),
		TotalStorage:         int32(totalStorage),
		TotalSavings:         int32(totalSavings),
		TotalPublicFiles:     int32(totalPublicFiles),
		TotalPublicDownloads: int32(totalPublicDownloads),
		TopDownloadedFiles:   topDownloadedFiles,
		RecentDownloads:      recentDownloads,
	}, nil
}

// GetAllFiles returns all files with uploader details for admin panel
func (r *queryResolver) GetAllFiles(ctx context.Context) ([]*model.File, error) {
	rows, err := r.DB.Query(ctx, `
		SELECT f.id, f.filename, f.filehash, f.filetype, f.filesize, 
			   f.is_public, f.is_public_shared, f.public_share_enabled_at, f.created_at,
			   u.id as owner_id, u.username, u.email, u.role,
			   psu.id as public_share_by_id, psu.username as public_share_by_username,
			   psu.email as public_share_by_email, psu.role as public_share_by_role,
			   fo.id as folder_id, fo.name as folder_name
		FROM files f
		JOIN users u ON f.owner_id = u.id
		LEFT JOIN users psu ON f.public_share_enabled_by = psu.id
		LEFT JOIN folders fo ON f.folder_id = fo.id
		ORDER BY f.created_at DESC
	`)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch all files: %v", err)
	}
	defer rows.Close()

	var files []*model.File
	for rows.Next() {
		var file model.File
		var owner model.User
		var publicShareEnabledBy *model.User
		var folder *model.Folder
		var createdAt, publicShareEnabledAt time.Time
		var publicShareEnabledAtPtr *time.Time
		var publicShareByID, publicShareByUsername, publicShareByEmail, publicShareByRole *string
		var folderID, folderName *string

		err := rows.Scan(
			&file.ID, &file.Filename, &file.Filehash, &file.Filetype, &file.Filesize,
			&file.IsPublic, &file.IsPublicShared, &publicShareEnabledAtPtr, &createdAt,
			&owner.ID, &owner.Username, &owner.Email, &owner.Role,
			&publicShareByID, &publicShareByUsername, &publicShareByEmail, &publicShareByRole,
			&folderID, &folderName,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan file: %v", err)
		}

		file.CreatedAt = createdAt.Format(time.RFC3339)
		file.Owner = &owner

		if publicShareEnabledAtPtr != nil {
			publicShareEnabledAt = *publicShareEnabledAtPtr
			formattedTime := publicShareEnabledAt.Format(time.RFC3339)
			file.PublicShareEnabledAt = &formattedTime
		}

		if publicShareByID != nil {
			publicShareEnabledBy = &model.User{
				ID:       *publicShareByID,
				Username: *publicShareByUsername,
				Email:    *publicShareByEmail,
				Role:     *publicShareByRole,
			}
			file.PublicShareEnabledBy = publicShareEnabledBy
		}

		if folderID != nil {
			folder = &model.Folder{
				ID:   *folderID,
				Name: *folderName,
			}
			file.Folder = folder
		}

		files = append(files, &file)
	}

	return files, nil
}

// GetAuditLogs is the resolver for the getAuditLogs field (Admin only).
func (r *queryResolver) GetAuditLogs(ctx context.Context, limit *int32, offset *int32, userID *string, action *string, resourceType *string) (*model.AuditLogConnection, error) {
	// fmt.Printf("GetAuditLogs called\n")
	
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		// fmt.Printf("GetAuditLogs: authentication error: %v\n", err)
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	// fmt.Printf("GetAuditLogs: user role = %s\n", user.Role)

	// Check if user is admin
	if user.Role != "admin" {
		fmt.Printf("GetAuditLogs: non-admin user trying to access\n")
		return nil, fmt.Errorf("admin access required")
	}

	// Set defaults
	if limit == nil {
		defaultLimit := int32(50)
		limit = &defaultLimit
	}
	if offset == nil {
		defaultOffset := int32(0)
		offset = &defaultOffset
	}

	// Build query with optional filters
	whereClause := "WHERE 1=1"
	args := []interface{}{}
	argIndex := 1

	if userID != nil {
		whereClause += fmt.Sprintf(" AND al.user_id = $%d", argIndex)
		args = append(args, *userID)
		argIndex++
	}
	if action != nil {
		whereClause += fmt.Sprintf(" AND al.action = $%d", argIndex)
		args = append(args, *action)
		argIndex++
	}
	if resourceType != nil {
		whereClause += fmt.Sprintf(" AND al.resource_type = $%d", argIndex)
		args = append(args, *resourceType)
		argIndex++
	}

	// Add limit and offset
	args = append(args, *limit+1, *offset) // +1 to check if there are more records

	query := fmt.Sprintf(`
		SELECT al.id, al.user_id, al.action, al.resource_type, al.resource_id, 
		       al.resource_name, al.details, al.ip_address, al.user_agent, al.created_at,
		       u.id, u.username, u.email, u.role
		FROM audit_logs al
		JOIN users u ON al.user_id = u.id
		%s
		ORDER BY al.created_at DESC
		LIMIT $%d OFFSET $%d
	`, whereClause, argIndex, argIndex+1)

	// fmt.Printf("GetAuditLogs: executing query: %s\n", query)
	// fmt.Printf("GetAuditLogs: args: %v\n", args)

	rows, err := r.DB.Query(ctx, query, args...)
	if err != nil {
		// fmt.Printf("GetAuditLogs: query error: %v\n", err)
		return nil, fmt.Errorf("failed to get audit logs: %v", err)
	}
	defer rows.Close()

	var logs []*model.AuditLog
	rowCount := 0
	for rows.Next() {
		rowCount++
		// fmt.Printf("GetAuditLogs: processing row %d\n", rowCount)
		var log model.AuditLog
		var user model.User
		var createdAt time.Time
		var resourceID *string
		var resourceName, details, ipAddress, userAgent *string
		var userIDFromAudit string // for al.user_id

		err := rows.Scan(
			&log.ID, &userIDFromAudit, &log.Action, &log.ResourceType, &resourceID,
			&resourceName, &details, &ipAddress, &userAgent, &createdAt,
			&user.ID, &user.Username, &user.Email, &user.Role,
		)
		if err != nil {
			// fmt.Printf("GetAuditLogs: scan error on row %d: %v\n", rowCount, err)
			continue
		}

		// fmt.Printf("GetAuditLogs: scanned log ID: %s, action: %s\n", log.ID, log.Action)

		log.User = &user
		log.CreatedAt = createdAt.Format(time.RFC3339)
		if resourceID != nil {
			log.ResourceID = resourceID
		}
		if resourceName != nil {
			log.ResourceName = resourceName
		}
		if details != nil {
			log.Details = details
		}
		if ipAddress != nil {
			log.IPAddress = ipAddress
		}
		if userAgent != nil {
			log.UserAgent = userAgent
		}

		logs = append(logs, &log)
	}

	// fmt.Printf("GetAuditLogs: total logs found: %d\n", len(logs))

	// Check if there are more records
	hasMore := int32(len(logs)) > *limit
	if hasMore {
		logs = logs[:*limit] // Remove the extra record
	}

	// Get total count
	countQuery := fmt.Sprintf("SELECT COUNT(*) FROM audit_logs al %s", whereClause)
	var totalCount int
	err = r.DB.QueryRow(ctx, countQuery, args[:len(args)-2]...).Scan(&totalCount)
	if err != nil {
		return nil, fmt.Errorf("failed to get total count: %v", err)
	}

	// fmt.Printf("GetAuditLogs: returning %d logs, totalCount: %d, hasMore: %t\n", len(logs), totalCount, hasMore)

	return &model.AuditLogConnection{
		Logs:       logs,
		TotalCount: int32(totalCount),
		HasMore:    hasMore,
	}, nil
}

// GetUserAuditLogs is the resolver for the getUserAuditLogs field.
func (r *queryResolver) GetUserAuditLogs(ctx context.Context, limit *int32, offset *int32) (*model.AuditLogConnection, error) {
	user, err := middleware.GetUserFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %v", err)
	}

	// Set defaults
	if limit == nil {
		defaultLimit := int32(50)
		limit = &defaultLimit
	}
	if offset == nil {
		defaultOffset := int32(0)
		offset = &defaultOffset
	}

	query := `
		SELECT al.id, al.action, al.resource_type, al.resource_id, 
		       al.resource_name, al.details, al.ip_address, al.user_agent, al.created_at
		FROM audit_logs al
		WHERE al.user_id = $1
		ORDER BY al.created_at DESC
		LIMIT $2 OFFSET $3
	`

	rows, err := r.DB.Query(ctx, query, user.ID, *limit+1, *offset)
	if err != nil {
		return nil, fmt.Errorf("failed to get user audit logs: %v", err)
	}
	defer rows.Close()

	var logs []*model.AuditLog
	for rows.Next() {
		var log model.AuditLog
		var createdAt time.Time
		var resourceID *string
		var resourceName, details, ipAddress, userAgent *string

		err := rows.Scan(
			&log.ID, &log.Action, &log.ResourceType, &resourceID,
			&resourceName, &details, &ipAddress, &userAgent, &createdAt,
		)
		if err != nil {
			continue
		}

		log.User = &model.User{
			ID:       user.ID,
			Username: user.Username,
			Email:    user.Email,
			Role:     user.Role,
		}
		log.CreatedAt = createdAt.Format(time.RFC3339)
		if resourceID != nil {
			log.ResourceID = resourceID
		}
		if resourceName != nil {
			log.ResourceName = resourceName
		}
		if details != nil {
			log.Details = details
		}
		if ipAddress != nil {
			log.IPAddress = ipAddress
		}
		if userAgent != nil {
			log.UserAgent = userAgent
		}

		logs = append(logs, &log)
	}

	// Check if there are more records
	hasMore := int32(len(logs)) > *limit
	if hasMore {
		logs = logs[:*limit] // Remove the extra record
	}

	// Get total count for this user
	var totalCount int
	err = r.DB.QueryRow(ctx, "SELECT COUNT(*) FROM audit_logs WHERE user_id = $1", user.ID).Scan(&totalCount)
	if err != nil {
		return nil, fmt.Errorf("failed to get total count: %v", err)
	}

	return &model.AuditLogConnection{
		Logs:       logs,
		TotalCount: int32(totalCount),
		HasMore:    hasMore,
	}, nil
}

// Mutation returns MutationResolver implementation.
func (r *Resolver) Mutation() MutationResolver { return &mutationResolver{r} }

// Query returns QueryResolver implementation.
func (r *Resolver) Query() QueryResolver { return &queryResolver{r} }

type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }

	func (r *queryResolver) generateSearchFacets(ctx context.Context, conditions []string, args []interface{}) (*model.SearchFacets, error) {
	whereClause := "WHERE " + strings.Join(conditions, " AND ")

	// MIME type facets
	mimeQuery := fmt.Sprintf(`
		SELECT
			CASE
				WHEN f.filetype LIKE 'image/%%' THEN 'Images'
				WHEN f.filetype LIKE 'video/%%' THEN 'Videos'
				WHEN f.filetype LIKE 'audio/%%' THEN 'Audio'
				WHEN f.filetype LIKE 'text/%%' THEN 'Text'
				WHEN f.filetype IN ('application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') THEN 'Documents'
				WHEN f.filetype LIKE 'application/%%' THEN 'Applications'
				ELSE 'Other'
			END as category,
			f.filetype,
			COUNT(*) as count
		FROM files f
		JOIN users u ON f.owner_id = u.id
		%s
		GROUP BY category, f.filetype
		ORDER BY count DESC
		LIMIT 20
	`, whereClause)

	mimeRows, err := r.DB.Query(ctx, mimeQuery, args...)
	if err != nil {
		return nil, err
	}
	defer mimeRows.Close()

	var mimeTypeFacets []*model.MimeTypeFacet
	for mimeRows.Next() {
		var facet model.MimeTypeFacet
		err := mimeRows.Scan(&facet.Category, &facet.Type, &facet.Count)
		if err != nil {
			continue
		}
		mimeTypeFacets = append(mimeTypeFacets, &facet)
	}

	// Uploader facets
	uploaderQuery := fmt.Sprintf(`
		SELECT u.username, u.id, COUNT(*) as count
		FROM files f
		JOIN users u ON f.owner_id = u.id
		%s
		GROUP BY u.username, u.id
		ORDER BY count DESC
		LIMIT 10
	`, whereClause)

	uploaderRows, err := r.DB.Query(ctx, uploaderQuery, args...)
	if err != nil {
		return nil, err
	}
	defer uploaderRows.Close()

	var uploaderFacets []*model.UploaderFacet
	for uploaderRows.Next() {
		var facet model.UploaderFacet
		err := uploaderRows.Scan(&facet.Username, &facet.UserID, &facet.Count)
		if err != nil {
			continue
		}
		uploaderFacets = append(uploaderFacets, &facet)
	}

	// Size bucket facets
	sizeQuery := fmt.Sprintf(`
		SELECT
			CASE
				WHEN f.filesize < 1048576 THEN 'Small (< 1MB)'
				WHEN f.filesize < 10485760 THEN 'Medium (1-10MB)'
				WHEN f.filesize < 104857600 THEN 'Large (10-100MB)'
				ELSE 'Huge (> 100MB)'
			END as range_label,
			CASE
				WHEN f.filesize < 1048576 THEN 0
				WHEN f.filesize < 10485760 THEN 1048576
				WHEN f.filesize < 104857600 THEN 10485760
				ELSE 104857600
			END as min_size,
			CASE
				WHEN f.filesize < 1048576 THEN 1048576
				WHEN f.filesize < 10485760 THEN 10485760
				WHEN f.filesize < 104857600 THEN 104857600
				ELSE NULL
			END as max_size,
			COUNT(*) as count
		FROM files f
		JOIN users u ON f.owner_id = u.id
		%s
		GROUP BY range_label, min_size, max_size
		ORDER BY min_size
	`, whereClause)

	sizeRows, err := r.DB.Query(ctx, sizeQuery, args...)
	if err != nil {
		return nil, err
	}
	defer sizeRows.Close()

	var sizeBucketFacets []*model.SizeBucketFacet
	for sizeRows.Next() {
		var facet model.SizeBucketFacet
		var maxSize *int32
		err := sizeRows.Scan(&facet.Range, &facet.Min, &maxSize, &facet.Count)
		if err != nil {
			continue
		}
		facet.Max = maxSize
		sizeBucketFacets = append(sizeBucketFacets, &facet)
	}

	return &model.SearchFacets{
		MimeTypes:   mimeTypeFacets,
		Uploaders:   uploaderFacets,
		SizeBuckets: sizeBucketFacets,
	}, nil
}

